     1	/**
     2	 * Event Service Client for Expo/React Native
     3	 * Fetches events from local API server (server-side Ticketmaster calls)
     4	 * This avoids exposing API keys in the client
     5	 * 
     6	 * ARCHITECTURE:
     7	 * - PRIMARY: Supabase (normalized, canonicalized events)
     8	 * - DEBUG: Direct API (/debug-direct-events) - for development only
     9	 * 
    10	 * IMPORTANT: All production traffic goes through Supabase only.
    11	 * The direct API endpoint is deprecated and only for debugging.
    12	 */
    13	
    14	// Local API server URL - MUST use host LAN IP for physical iPhone
    15	// The server runs on the host machine and Expo Go on iPhone needs the host IP
    16	const API_BASE_URL = 'http://192.168.68.101:8080';
    17	
    18	// Feature flag: Enable fallback to direct API (development only!)
    19	// Set to false in production - all traffic should go through Supabase
    20	const USE_DIRECT_API_FALLBACK = false;
    21	
    22	const TIMEOUT = 15000;
    23	
    24	/**
    25	 * Generic fetch wrapper
    26	 */
    27	async function fetchFromAPI(endpoint = '/supabase-events') {
    28	  try {
    29	    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    30	      method: 'GET',
    31	      headers: {
    32	        'Accept': 'application/json',
    33	        'Content-Type': 'application/json',
    34	      },
    35	    });
    36	    
    37	    if (!response.ok) {
    38	      console.warn(`[EventService] API error: ${response.status}`);
    39	      return { error: `HTTP ${response.status}` };
    40	    }
    41	    
    42	    return await response.json();
    43	  } catch (error) {
    44	    console.warn(`[EventService] Network error: ${error.message}`);
    45	    return { error: error.message };
    46	  }
    47	}
    48	
    49	/**
    50	 * Fetch events from Supabase (normalized storage)
    51	 * This is the PRIMARY and ONLY source for events in production
    52	 */
    53	export async function fetchFromSupabase() {
    54	  const data = await fetchFromAPI('/supabase-events');
    55	  
    56	  if (data.error || !data.events) {
    57	    console.error('[EventService] Supabase fetch failed:', data.error);
    58	    return {
    59	      events: [],
    60	      sources: [],
    61	      metadata: {
    62	        data_source: 'supabase',
    63	        fallback_used: false,
    64	        error: data.error || 'No events returned'
    65	      }
    66	    };
    67	  }
    68	  
    69	  return {
    70	    events: data.events || [],
    71	    sources: data.sources || [],
    72	    count: data.count || 0,
    73	    metadata: {
    74	      data_source: 'supabase',
    75	      fallback_used: false,
    76	      available_sources: data.sources || [],
    77	      total_count: data.count || 0,
    78	      last_ingested_at: data.last_ingested_at || null,
    79	      ingestion_stats: data.ingestion_stats || null
    80	    }
    81	  };
    82	}
    83	
    84	/**
    85	 * DEBUG ONLY: Fetch events directly from provider APIs
    86	 * 
    87	 * WARNING: This endpoint returns RAW, non-normalized data.
    88	 * Do NOT use in production - data will not have canonical sources,
    89	 * consistent schemas, or proper deduplication.
    90	 * 
    91	 * Available at: /debug-direct-events
    92	 */
    93	export async function fetchDirectFromAPIs() {
    94	  console.warn('[EventService] WARNING: Using deprecated direct API endpoint');
    95	  
    96	  const data = await fetchFromAPI('/debug-direct-events');
    97	  
    98	  if (data.error || !data.ticketmaster) {
    99	    return {
   100	      events: [],
   101	      sources: [],
   102	      metadata: {
   103	        data_source: 'direct_api',
   104	        debug_only: true,
   105	        warning: 'DEPRECATED: Raw data from provider APIs, not normalized'
   106	      }
   107	    };
   108	  }
   109	  
   110	  const allEvents = [];
   111	  
   112	  if (data.ticketmaster?.events) {
   113	    allEvents.push(...data.ticketmaster.events);
   114	  }
   115	  
   116	  if (data.otherSources?.sources?.kulturhuset) {
   117	    allEvents.push(...data.otherSources.sources.kulturhuset);
   118	  }
   119	  
   120	  if (data.otherSources?.sources?.malmolive) {
   121	    allEvents.push(...data.otherSources.sources.malmolive);
   122	  }
   123	  
   124	  return {
   125	    events: allEvents,
   126	    sources: data.sources || [],
   127	    count: allEvents.length,
   128	    metadata: {
   129	      data_source: 'direct_api',
   130	      debug_only: true,
   131	      warning: 'DEPRECATED: Raw data from provider APIs, not normalized'
   132	    }
   133	  };
   134	}
   135	
   136	/**
   137	 * Fetch events - Supabase only (production mode)
   138	 * This is the standard function to use in the app
   139	 */
   140	export async function fetchEventsSupabaseOnly() {
   141	  return fetchFromSupabase();
   142	}
   143	
   144	/**
   145	 * Fetch events with fallback (development mode only)
   146	 * WARNING: Only enabled when USE_DIRECT_API_FALLBACK=true
   147	 */
   148	export async function fetchEventsWithFallback() {
   149	  // Try Supabase first (always)
   150	  const supabaseData = await fetchFromSupabase();
   151	  
   152	  if (supabaseData.events.length > 0) {
   153	    return supabaseData;
   154	  }
   155	  
   156	  // Only use fallback if explicitly enabled
   157	  if (USE_DIRECT_API_FALLBACK) {
   158	    console.warn('[EventService] WARNING: Falling back to direct API (development only!)');
   159	    return fetchDirectFromAPIs();
   160	  }
   161	  
   162	  // No fallback - return empty with clear error
   163	  return {
   164	    events: [],
   165	    sources: [],
   166	    metadata: {
   167	      data_source: 'supabase',
   168	      fallback_used: false,
   169	      error: 'No events in Supabase. Fallback disabled.',
   170	      action_required: 'Run ingestion pipeline to populate Supabase'
   171	    }
   172	  };
   173	}
   174	
   175	/**
   176	 * Legacy function - use fetchEventsSupabaseOnly() instead
   177	 */
   178	export async function fetchAllEventsViaServer() {
   179	  return fetchEventsSupabaseOnly();
   180	}
   181	
   182	/**
   183	 * Health check for API server and ingestion status
   184	 */
   185	export async function checkAPIHealth() {
   186	  const data = await fetchFromAPI('/health');
   187	  
   188	  if (data.error) {
   189	    return { 
   190	      connected: false, 
   191	      error: data.error 
   192	    };
   193	  }
   194	  
   195	  return {
   196	    connected: true,
   197	    status: data.status,
   198	    ticketmasterKey: data.ticketmasterKey,
   199	    supabase: data.supabase,
   200	    ingestion: data.ingestion || null,
   201	  };
   202	}
   203	
   204	// Export for use in App.js
   205	export const fetchEvents = fetchEventsSupabaseOnly;
   206	export const fetchEventsFromSupabase = fetchEventsSupabaseOnly; // Alias for clarity
   207	export { API_BASE_URL, USE_DIRECT_API_FALLBACK };
